// Kinetic: big-wave-surfing page script (generated by kinetic-tools/build/build.py)
(function () {
  const PAGE = {
    key: "big-wave-surfing",
    v1: "Physics: nailed it 🌊",
    b1: "You've got the physics of giant waves: energy, swell, seabed focusing and tow-in speed. Skim the chapters for anything you missed, then see “Learn abroad” for tow-in and rescue training. Knowing the science is a great start; it isn't the same as big-wave training.",
    b2: "You have the basics. Fill the gaps below, especially energy and height squared and why whitewater won't hold you up.",
    b3: "No shame in that: this is exactly what the chapters are for. Read the ones linked below, then take the challenge again.",
    whereLabel: "Where to learn it abroad →",
    whereHref: "#abroad",
    disclaimer: "<strong>Self-check only.</strong> This quiz is a learning aid. It is not a certification or a big-wave qualification, and a high score does not mean you're ready to paddle or tow into big surf. Big-wave surfing needs years of surfing, water-safety and rescue training and a trained team with a qualified instructor; never go out in big waves without one."
  };
  const CHAPTERS = {
    "ch-size":    "Ch 1 · How big is big",
    "ch-energy":  "Ch 2 · Energy grows with height squared",
    "ch-swell":   "Ch 3 · Long-period swell",
    "ch-canyon":  "Ch 4 · Seabed shape",
    "ch-tow":     "Ch 5 · Tow-in",
    "ch-wipeout": "Ch 6 · Wipeouts, foam & rescue"
  };
  const QUESTIONS = [
    { ch: "ch-size",
      q: "How is a big wave's height measured for records?",
      o: ["From the trough in front of the wave to its crest", "From the seabed to the crest", "From the beach to the crest", "From the surfer's feet to the crest"], a: 0,
      e: "Records measure the face from trough to crest. Guinness lists the largest wave surfed as 26.21 m, ridden at Nazaré on 29 October 2020." },
    { ch: "ch-size",
      q: "How was the 26.21 m record wave measured?",
      o: ["With a buoy under the wave", "From video frames corrected for the camera's position and tilt, using known objects like the surfer for scale", "By the surfer's own estimate", "With a tape measure from a helicopter"], a: 1,
      e: "Guinness says frames were extracted from the footage, corrected geometrically for the camera, and known objects such as Steudtner himself were used to turn pixels into feet." },
    { ch: "ch-energy",
      q: "In linear wave theory, how does a wave's energy grow with its height H?",
      o: ["With H", "With √H", "With H²", "It doesn't change"], a: 2,
      e: "Energy per square metre is ⅛ρgH². Double the height and the energy quadruples." },
    { ch: "ch-energy",
      q: "About how much more energy does a 15 m wave carry than a 3 m one?",
      o: ["5 times", "10 times", "15 times", "25 times"], a: 3,
      e: "(15 ÷ 3)² = 25. That's why \"five times taller\" is far more than five times as dangerous." },
    { ch: "ch-energy",
      q: "Roughly how much energy is stored in each square metre of sea under a 15 m wave (seawater, ⅛ρgH²)?",
      o: ["About 283 kJ", "About 28 J", "About 2.8 kJ", "About 28 MJ"], a: 0,
      e: "1,025 × 9.81 × 15² ÷ 8 ≈ 283,000 J ≈ 283 kJ, close to a one-tonne car's energy at about 85 km/h." },
    { ch: "ch-swell",
      q: "What does a big-wave spot usually need to \"turn on\"?",
      o: ["A local breeze", "Powerful long-period swell from a distant storm, arriving from the right direction", "A high tide only", "A full moon"], a: 1,
      e: "Long-period swell from distant storms carries the energy; the spot's seabed focuses it only from certain directions." },
    { ch: "ch-swell",
      q: "In deep water, how long are the waves of a 16-second swell (L = gT² ÷ 2π)?",
      o: ["About 40 m", "About 160 m", "About 400 m", "About 4 km"], a: 2,
      e: "9.81 × 16² ÷ 6.283 ≈ 400 m. Longer periods mean longer, faster waves." },
    { ch: "ch-swell",
      q: "Swell energy travels at the group speed. For a 16 s swell in deep water, about how fast is that?",
      o: ["About 4.5 km/h", "About 450 km/h", "About 90 km/h", "About 45 km/h, half the crest speed"], a: 3,
      e: "Crest speed gT ÷ 2π ≈ 25 m/s; energy moves at half that, 12.5 m/s ≈ 45 km/h, so 1,000 km takes about 22 hours." },
    { ch: "ch-canyon",
      q: "Once a wave feels the bottom, how does its speed change with depth?",
      o: ["It's faster over deeper water and slower over shallow water", "It's faster over shallow water", "Depth makes no difference", "It stops completely in deep water"], a: 0,
      e: "In shallow water c ≈ √(g × depth). Part of a crest over deeper water runs ahead, so the crest bends: refraction." },
    { ch: "ch-canyon",
      q: "Portugal's Instituto Hidrográfico explains the big waves near Nazaré mainly by…",
      o: ["Underwater volcanoes", "Refraction caused by a submarine canyon, combined with nearshore dynamics near its head", "Tides from the Mediterranean", "Ships' wakes"], a: 1,
      e: "The canyon head reaches about 150 m deep while the seabed beside it is no more than 20 m, so swell crossing it bends and focuses energy towards the shore." },
    { ch: "ch-tow",
      q: "Using the rule of thumb that a wave breaks when its height is about 0.78 × the depth, where does a 15 m wave break?",
      o: ["In about 2 m of water", "In about 12 m", "In about 19 m of water", "In about 100 m"], a: 2,
      e: "15 ÷ 0.78 ≈ 19.2 m. Real reefs and canyons break waves in their own ways; this is a beach rule of thumb." },
    { ch: "ch-tow",
      q: "Roughly how fast is a 15 m wave moving as it breaks (c ≈ √(g × depth), depth ≈ 19 m)?",
      o: ["About 5 km/h", "About 15 km/h", "About 150 km/h", "About 49 km/h"], a: 3,
      e: "√(9.81 × 19.2) ≈ 13.7 m/s ≈ 49 km/h. That's why many big-wave surfers get towed in behind a jet ski to match the wave's speed." },
    { ch: "ch-tow",
      q: "In the WSL's TUDOR Nazaré Big Wave Challenge, what must every team member be able to do?",
      o: ["Safely tow in and rescue their partner", "Surf without a leash", "Paddle in without help", "Judge the event"], a: 0,
      e: "The WSL says safety is paramount: the one-day tow-in event runs only on a swell of 25 feet or more, and all team members must be able to tow in and rescue their partners." },
    { ch: "ch-wipeout",
      q: "Why does whitewater give a surfer less support than solid water?",
      o: ["It's colder", "It's full of air, so it's less dense and gives less buoyant lift", "It's saltier", "It moves too slowly"], a: 1,
      e: "Archimedes: lift equals the weight of water displaced. Air mixed in lowers the mixture's density, so a body, board or float gets less lift." },
    { ch: "ch-wipeout",
      q: "The ISA/ILS water safety accreditation includes which fitness test?",
      o: ["A 10 km run", "A breath-hold test only", "A run-swim-run in the surf, completed within 5 minutes", "None"], a: 2,
      e: "The ISA's course page lists a minimum 100 m run, a swim of at least 100 m through the surf and impact zone, and a 100 m run, plus board rescue, first aid and CPR." }
  ];

  // ---------- QUIZ RENDER ----------
  const list = document.getElementById("quiz-list");
  const dots = document.getElementById("quiz-dots");
  const prog = document.getElementById("quiz-progress");
  const progLabel = document.getElementById("quiz-progress-label");
  const warn = document.getElementById("quiz-warn");
  const resultBox = document.getElementById("quiz-result");
  let graded = false;

  function esc(s) { return s.replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  QUESTIONS.forEach((item, i) => {
    const n = i + 1;
    const div = document.createElement("div");
    div.className = "q";
    div.id = "q" + n;
    div.dataset.index = i;
    div.innerHTML =
      `<span class="qtag">${esc(CHAPTERS[item.ch].split(" · ")[1])}</span>` +
      `<span class="qnum">Question ${n} / ${QUESTIONS.length}</span>` +
      `<h3>${esc(item.q)}</h3>` +
      `<div class="opts" role="radiogroup" aria-label="Question ${n}">` +
      item.o.map((opt, j) =>
        `<label class="opt"><input type="radio" name="q${n}" value="${j}"><span>${esc(opt)}</span><span class="mark"></span></label>`
      ).join("") +
      `</div><div class="explain" aria-live="polite"></div>`;
    list.appendChild(div);

    const d = document.createElement("a");
    d.href = "#q" + n; d.textContent = n; d.id = "dot" + n;
    d.setAttribute("aria-label", "Go to question " + n);
    dots.appendChild(d);
  });

  function answeredCount() {
    return QUESTIONS.filter((_, i) => document.querySelector(`input[name="q${i + 1}"]:checked`)).length;
  }
  function updateProgress() {
    const c = answeredCount();
    prog.style.width = (c / QUESTIONS.length * 100) + "%";
    progLabel.textContent = `${c} of ${QUESTIONS.length} answered`;
  }

  list.addEventListener("change", (ev) => {
    if (graded || ev.target.type !== "radio") return;
    const q = ev.target.closest(".q");
    q.querySelectorAll(".opt").forEach(l => l.classList.toggle("sel", l.querySelector("input").checked));
    document.getElementById("dot" + (+q.dataset.index + 1)).classList.add("answered");
    updateProgress();
    warn.style.display = "none";
  });

  function grade() {
    const unanswered = QUESTIONS.length - answeredCount();
    if (unanswered > 0 && !document.getElementById("quiz-submit").dataset.confirmed) {
      warn.textContent = `${unanswered} question${unanswered > 1 ? "s" : ""} unanswered. They'll count as wrong. Press submit again to score anyway.`;
      warn.style.display = "block";
      document.getElementById("quiz-submit").dataset.confirmed = "1";
      return;
    }
    graded = true;
    let score = 0;
    const wrongChapters = new Map();
    QUESTIONS.forEach((item, i) => {
      const n = i + 1;
      const qEl = document.getElementById("q" + n);
      const picked = document.querySelector(`input[name="q${n}"]:checked`);
      const pickedIdx = picked ? +picked.value : -1;
      const right = pickedIdx === item.a;
      if (right) score++;
      else wrongChapters.set(item.ch, (wrongChapters.get(item.ch) || []).concat(n));
      qEl.classList.add("graded", right ? "right" : (picked ? "wrong" : "skipped"));
      qEl.querySelectorAll("input").forEach(inp => inp.disabled = true);
      qEl.querySelectorAll(".opt").forEach((lab, j) => {
        if (j === item.a) { lab.classList.add("correct"); lab.querySelector(".mark").textContent = "✓ correct"; }
        else if (j === pickedIdx) { lab.classList.add("incorrect"); lab.querySelector(".mark").textContent = "✗ your pick"; }
      });
      const ex = qEl.querySelector(".explain");
      ex.innerHTML = `<span class="verdict">${right ? "Correct." : (picked ? "Not quite." : "Skipped.")}</span> ${esc(item.e)}` +
        (right ? "" : `<br><a class="chlink" href="#${item.ch}" data-wrong-link="${item.ch}">Read ${esc(CHAPTERS[item.ch])} →</a>`);
      const dot = document.getElementById("dot" + n);
      dot.classList.remove("answered"); dot.classList.add(right ? "right" : "wrong");
    });

    const pct = score / QUESTIONS.length;
    let lvl, title, blurb;
    if (pct >= 0.8) { lvl = "lvl-ready"; title = PAGE.v1; blurb = PAGE.b1; }
    else if (pct >= 0.55) { lvl = "lvl-close"; title = "Nearly there. Brush up on a couple of chapters"; blurb = PAGE.b2; }
    else { lvl = "lvl-brush"; title = "Brush up first"; blurb = PAGE.b3; }

    resultBox.className = "result show " + lvl;
    const chItems = [...wrongChapters.entries()].map(([ch, qs]) =>
      `<li><a href="#${ch}" data-summary-link="${ch}">${esc(CHAPTERS[ch])}</a> <span class="small">(question${qs.length > 1 ? "s" : ""} ${qs.join(", ")})</span></li>`).join("");
    resultBox.innerHTML =
      `<div class="score" id="quiz-score">${score}<small> / ${QUESTIONS.length}</small></div>` +
      `<h3 id="quiz-verdict">${title}</h3><p>${blurb}</p>` +
      `<div class="result-note" id="quiz-disclaimer" role="note">${PAGE.disclaimer}</div>` +
      (chItems ? `<strong>Chapters to read:</strong><ul id="quiz-revisit">${chItems}</ul>` : `<p><strong>Perfect score.</strong> The chapters still have the worked numbers if you want to go deeper.</p>`) +
      `<div class="actions"><button class="btn btn-ghost" type="button" id="quiz-retake">↺ Retake the challenge</button><a class="btn btn-ghost" href="${PAGE.whereHref || "#where"}">${PAGE.whereLabel}</a></div>`;
    document.getElementById("quiz-retake").addEventListener("click", resetQuiz);
    document.getElementById("quiz-submit").style.display = "none";
    warn.style.display = "none";
    resultBox.scrollIntoView({ behavior: "smooth", block: "start" });
    try { localStorage.setItem("kinetic-" + PAGE.key + "-last", JSON.stringify({ score, of: QUESTIONS.length, at: Date.now() })); } catch (e) {}
  }

  function resetQuiz() {
    graded = false;
    resultBox.className = "result"; resultBox.innerHTML = "";
    document.querySelectorAll(".q").forEach(q => {
      q.className = "q";
      q.querySelector(".explain").innerHTML = "";
      q.querySelectorAll("input").forEach(i => { i.checked = false; i.disabled = false; });
      q.querySelectorAll(".opt").forEach(l => { l.className = "opt"; l.querySelector(".mark").textContent = ""; });
    });
    document.querySelectorAll("#quiz-dots a").forEach(d => d.className = "");
    const sub = document.getElementById("quiz-submit");
    sub.style.display = ""; delete sub.dataset.confirmed;
    updateProgress();
    document.getElementById("q1").scrollIntoView({ behavior: "smooth", block: "start" });
  }

  document.getElementById("quiz-submit").addEventListener("click", grade);
  document.getElementById("quiz-reset").addEventListener("click", resetQuiz);
  updateProgress();

  // Expose for automated tests
  window.KINETIC_QUIZ = { QUESTIONS, CHAPTERS, grade, resetQuiz };


  // ---------- BIG-WAVE LAB ----------
  // Linear wave theory. E = ρgH²/8 (ρ = 1025). Deep water: L = gT²/2π, group speed = gT/4π.
  // Breaking: depth ≈ H/0.78, speed ≈ √(g d). Drop: √(2gH), frictionless upper bound. Bar = energy vs the 26.21 m record.
  (function () {
    const $ = id => document.getElementById(id);
    if (!$("bw-H")) return;
    const g = 9.81, RHO = 1025, REC = 26.21;
    const fmt = n => Math.round(n).toLocaleString("en-IN");
    function update() {
      const H = +$("bw-H").value, T = +$("bw-T").value;
      $("bw-H-o").textContent = H + " m";
      $("bw-T-o").textContent = T + " s";
      const E = RHO * g * H * H / 8, L = g * T * T / (2 * Math.PI), cg = g * T / (4 * Math.PI) * 3.6;
      const db = H / 0.78, cb = Math.sqrt(g * db) * 3.6, drop = Math.sqrt(2 * g * H) * 3.6;
      $("bw-E3").textContent = (H * H / 9).toFixed(1) + " ×";
      $("bw-E").textContent = fmt(E / 1000) + " kJ";
      $("bw-L").textContent = fmt(L) + " m";
      $("bw-cg").textContent = cg.toFixed(1) + " km/h";
      $("bw-db").textContent = db.toFixed(1) + " m";
      $("bw-cb").textContent = Math.round(cb) + " km/h";
      $("bw-drop").textContent = Math.round(drop) + " km/h";
      $("bw-rec").textContent = Math.round(H / REC * 100) + "%";
      $("bw-bar").style.width = Math.min(100, H * H / (REC * REC) * 100).toFixed(0) + "%";
    }
    ["bw-H", "bw-T"].forEach(id => $(id).addEventListener("input", update));
    update();
  })();

  // ---------- LEVEL TABS ----------
  const tabs = document.querySelectorAll(".lvl-tabs button");
  tabs.forEach(btn => btn.addEventListener("click", () => {
    tabs.forEach(b => b.setAttribute("aria-selected", b === btn ? "true" : "false"));
    document.querySelectorAll(".lvl-panel").forEach(p => p.classList.toggle("show", p.id === btn.getAttribute("aria-controls")));
  }));
  // a link or URL hash to #lvl-x opens that tab (and scrolls to the tabs), even after the visitor switched tabs
  const openLvl = (hash, scroll) => {
    const btn = /^#lvl-[\w-]+$/.test(hash || "") && [...tabs].find(b => "#" + b.getAttribute("aria-controls") === hash);
    if (!btn) return false;
    if (btn.getAttribute("aria-selected") !== "true") btn.click();
    if (scroll) { (btn.closest(".lvl-tabs") || btn).scrollIntoView({ block: "start" }); btn.focus({ preventScroll: true }); }
    return true;
  };
  document.addEventListener("click", e => {
    const a = e.target.closest && e.target.closest('a[href^="#lvl-"]');
    if (a && openLvl(a.getAttribute("href"), true)) { e.preventDefault(); if (location.hash !== a.getAttribute("href")) history.pushState(null, "", a.getAttribute("href")); }
  });
  window.addEventListener("hashchange", () => openLvl(location.hash, true));
  openLvl(location.hash, true);

  // ---------- STICKY NAV ACTIVE STATE ----------
  const navLinks = [...document.querySelectorAll(".sectionnav a[href^='#']")];
  const targets = navLinks.map(a => document.querySelector(a.getAttribute("href"))).filter(Boolean);
  if ("IntersectionObserver" in window) {
    const io = new IntersectionObserver(entries => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          navLinks.forEach(a => a.classList.toggle("active", a.getAttribute("href") === "#" + en.target.id));
        }
      });
    }, { rootMargin: "-45% 0px -50% 0px" });
    targets.forEach(t => io.observe(t));
  }

  // ---------- MOBILE NAV: edge fades + keep the active link in view ----------
  (function () {
    const snav = document.querySelector(".sectionnav");
    if (!snav) return;
    const fades = () => {
      const max = snav.scrollWidth - snav.clientWidth;
      snav.classList.toggle("fade-l", max > 4 && snav.scrollLeft > 4);
      snav.classList.toggle("fade-r", max > 4 && snav.scrollLeft < max - 4);
    };
    snav.addEventListener("scroll", fades, { passive: true });
    window.addEventListener("resize", fades);
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(fades);
    fades();
    const keep = () => {
      const a = snav.querySelector("a.active");
      if (!a || snav.scrollWidth <= snav.clientWidth + 4) return;
      const r = a.getBoundingClientRect(), n = snav.getBoundingClientRect();
      if (r.left < n.left + 16 || r.right > n.right - 40) snav.scrollBy({ left: r.left - n.left - 20, behavior: "smooth" });
    };
    if ("MutationObserver" in window) {
      const mo = new MutationObserver(keep);
      snav.querySelectorAll("a").forEach(a => mo.observe(a, { attributes: true, attributeFilter: ["class"] }));
    }
  })();
})();
